local VERSION='9.0.0'
local simulations, decisions, debriefs = {}, {}, {}
local function uid(p)return('%s-%s-%04d'):format(p,os.time(),math.random(0,9999))end
exports('StartAdaptiveTrainingV9',function(learner,scenario,difficulty)local item={id=uid('TRAIN'),learner=learner,scenario=scenario,difficulty=math.max(1,math.min(5,tonumber(difficulty)or 1)),status='active',decisions={},startedAt=os.time()};simulations[item.id]=item;return item.id,item end)
exports('ScoreClinicalDecisionV9',function(sessionId,decision,expected,elapsed)local session=simulations[tostring(sessionId)];if not session then return false,'Training session not found.'end;local accurate=tostring(decision)==tostring(expected);local timeScore=math.max(0,100-(tonumber(elapsed)or 0)*2);local score=math.floor((accurate and 70 or 0)+timeScore*.3);local item={id=uid('DEC'),sessionId=sessionId,decision=decision,expected=expected,accurate=accurate,elapsed=elapsed,score=score,createdAt=os.time()};decisions[item.id]=item;session.decisions[#session.decisions+1]=item;return true,item end)
exports('GenerateAdaptiveDebriefV9',function(sessionId)local session=simulations[tostring(sessionId)];if not session then return false,'Training session not found.'end;local total=0;for _,d in ipairs(session.decisions)do total=total+(d.score or 0)end;local avg=#session.decisions>0 and math.floor(total/#session.decisions)or 0;local item={id=uid('DEBRIEF'),sessionId=sessionId,average=avg,strengths={},remediation={},createdAt=os.time()};if avg>=80 then item.strengths={'clinical_reasoning','timeliness'}else item.remediation={'protocol_review','repeat_simulation'}end;debriefs[item.id]=item;session.status='completed';return true,item end)
exports('GetV9TrainingBoard',function()return{version=VERSION,simulations=simulations,decisions=decisions,debriefs=debriefs,generatedAt=os.time()}end)
CreateThread(function()Wait(5800);print('[dpn-medical-training] v9 adaptive simulation and competency debrief active')end)
